    ->withPaths([__DIR__.'/packages', __DIR__.'/products', __DIR__.'/tests', __DIR__.'/scripts'])
    ->withSkip([__DIR__.'/packages/*/vendor', __DIR__.'/products/*/vendor', ...glob(__DIR__.'/packages/*/database/migrations', GLOB_ONLYDIR), ...glob(__DIR__.'/products/*/database/migrations', GLOB_ONLYDIR)])
