    ->withSets([LaravelSetList::LARAVEL_CODE_QUALITY, LaravelSetList::LARAVEL_COLLECTION, LaravelSetList::LARAVEL_TYPE_DECLARATIONS])
    ->withImportNames(removeUnusedImports: true);
